#include <iostream>
#include <memory>
#include <vector>

// A generic resource class
class Resource {
public:
    Resource(int id) : id_(id) { std::cout << "Acquiring Resource " << id_ << std::endl; }
    ~Resource() { std::cout << "Destroying Resource " << id_ << std::endl; }
    int get_id() const { return id_; }
private:
    int id_;
};

int main() {
    // Deleter 1: standard deletion with a message
    auto deleter1 = [](Resource* r) {
        std::cout << "Custom Deleter 1: Deleting Resource " << r->get_id() << std::endl;
        delete r;
    };

    // Deleter 2: another custom action
    auto deleter2 = [](Resource* r) {
        std::cout << "Custom Deleter 2: Releasing Resource " << r->get_id() << " to a pool." << std::endl;
        delete r; // For this example, we still delete
    };

    // Both shared_ptr objects have the same type: std::shared_ptr<Resource>
    std::shared_ptr<Resource> sp1(new Resource(101), deleter1);
    std::shared_ptr<Resource> sp2(new Resource(202), deleter2);

    // They can be stored in the same container because their types match
    std::vector<std::shared_ptr<Resource>> resources;
    resources.push_back(sp1);
    resources.push_back(sp2);

    // sp1 can be assigned to a variable of the same base shared_ptr type
    std::shared_ptr<Resource> sp3 = sp1; // Shares ownership with sp1

    std::cout << "Exiting main. Resources will be cleaned up." << std::endl;
    // When sp1/sp3 and sp2 go out of scope, their respective custom deleters are called.
    return 0;
}
